import{_ as t,h as n,i as a,c as i,v as r,p as m,x as o,m as l,e as p,S as c}from"./chunks/framework.Dvtg8yj2.js";const C=JSON.parse('{"title":"压缩记忆 / Compressive Transformer","description":"","frontmatter":{"title":"压缩记忆 / Compressive Transformer","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/compressive-transformer.md","filePath":"llm/compressive-transformer.md","lastUpdated":1788454257000}'),d={name:"llm/compressive-transformer.md"};function f(h,e,_,E,T,u){const s=n("Mermaid");return a(),i("div",null,[e[1]||(e[1]=r('<h1 id="压缩记忆-compressive-transformer" tabindex="-1">压缩记忆 / Compressive Transformer <a class="header-anchor" href="#压缩记忆-compressive-transformer" aria-label="Permalink to &quot;压缩记忆 / Compressive Transformer&quot;">​</a></h1><div class="epigraph"><p>旧激活不必丢掉；把它们压进更短的记忆槽，模型仍能回看被滑窗放弃的那段历史。</p><footer>—— Rae 等，Compressive Transformers for Long-Range Sequence Modelling，2020</footer></div><p>Transformer-XL 给每层接上一截过去的激活当记忆，窗口外的 token 以「未经压缩的 KV 式状态」被引用，再往前就丢弃。Rae 等人 2020 年的 Compressive Transformer 在 XL 的记忆之外再加一层<strong>压缩记忆</strong>：oldest 的那截激活经过卷积、池化或注意力池化，变成更少的槽，而不是直接出队。它是长程序列建模在预训练时代早期的一条主路——对象是字符级与文档级语言建模（enwik8、PG-19），不是后来的 128k 指令模型，但「把旧状态压实而不是扔掉」这一想法，直接通向 Infini-Attention 与各类 KV 压缩。本篇只写压缩记忆本身。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>因果自注意力的代价随当前段长度二次涨，所以实现上总是分段：当前段长度 \\(n\\)，再附带过去 \\(m\\) 个激活作为记忆。Transformer-XL 的 \\(m\\) 个槽是无损的（相对丢弃而言），但 \\(m\\) 仍受显存限制。再早的历史只能消失。对小说、代码、长文语言建模，消失的那截里仍有主题、人物、函数定义。问题是：能否用 \\(m_c\\ll m\\) 个槽近似那截历史，使总状态 \\(m+m_c\\) 仍可放进设备，同时比「同等槽数的无损短记忆」记住更远的东西。</p><p>压缩必须可导，且不能要求看见未来。它还要和分段训练兼容：梯度通过压缩函数回到更早的段，但 BPTT 深度有限，不能真的反传到无限过去。Rae 等人用辅助重构损失，强迫压缩槽仍能还原被压掉的激活，否则记忆会塌成无信息的平均值。<span class="marginnote">压缩记忆不是检索器。没有外部分解析文档，也没有离散指针。它是层内状态的有损编码，精度由压缩率 \\(c\\) 和压缩函数的表达力共同决定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="两级记忆" tabindex="-1">两级记忆 <a class="header-anchor" href="#两级记忆" aria-label="Permalink to &quot;两级记忆&quot;">​</a></h3><p>当前段激活记为 \\(H\\in\\mathbb{R}^{n\\times d}\\)。无损记忆 \\(M\\in\\mathbb{R}^{m\\times d}\\) 保存最近若干段留下的激活。当 \\(M\\) 要淘汰最老的 \\(c\\) 个向量时，不是删除，而是送入压缩函数 \\(f\\)，产出 \\(m_c\\) 增长所用的新压缩槽，写入压缩记忆 \\(C\\in\\mathbb{R}^{m_c\\times d}\\)（\\(m_c\\) 以压缩率维持上限）。注意力的可见集是</p> \\[[C;\\,M;\\,H] \\]<p>对当前 \\(H\\) 做因果掩码，对 \\(M\\) 与 \\(C\\) 做「可以全看、但它们内部不再更新」的停用梯度或截断 BPTT，具体依实现。位置偏置沿用 XL 的相对位置方案，压缩槽对应更粗、更远的距离桶。</p><h3 id="压缩函数" tabindex="-1">压缩函数 <a class="header-anchor" href="#压缩函数" aria-label="Permalink to &quot;压缩函数&quot;">​</a></h3><p>\\(f\\) 可以把每 \\(c\\) 个无损槽映射成 1 个压缩槽。候选包括：沿时间的一维卷积、最大/平均池化、以及以可学习查询去池化那 \\(c\\) 个键的注意力。卷积保留局部顺序，池化最便宜，注意力池化最能挑「该记住的」激活。压缩率 \\(c\\) 是主超参：</p> \\[|C|\\approx \\frac{\\text{被淘汰的无损步数}}{c} \\]<p>\\(c\\) 越大，同一 \\(m_c\\) 预算能覆盖越远的历史，单槽信息越糊。</p><h3 id="辅助重构" tabindex="-1">辅助重构 <a class="header-anchor" href="#辅助重构" aria-label="Permalink to &quot;辅助重构&quot;">​</a></h3><p>仅靠语言建模损失，压缩器可能学成常数。Rae 等人加一项：从压缩槽重构被压缩的那截激活，或重构其内容的代理目标。这项损失把 \\(f\\) 钉在「可逆到有用」的区域，而不是只最小化当前交叉熵。推理时关掉重构头即可。</p>',17)),(a(),m(c,null,{default:o(()=>[p(s,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20LR%0A%20%20H%5B%22%E5%BD%93%E5%89%8D%E6%AE%B5%20H%22%5D%20--%3E%20M%5B%22%E6%97%A0%E6%8D%9F%E8%AE%B0%E5%BF%86%20M%22%5D%0A%20%20M%20--%3E%20F%5B%22%E5%8E%8B%E7%BC%A9%E5%87%BD%E6%95%B0%20f%22%5D%0A%20%20F%20--%3E%20C%5B%22%E5%8E%8B%E7%BC%A9%E8%AE%B0%E5%BF%86%20C%22%5D%0A%20%20C%20--%3E%20A%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E5%8F%AF%E8%A7%81%E9%9B%86%22%5D%0A%20%20M%20--%3E%20A%0A%20%20H%20--%3E%20A%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制可以看成时间轴上的金字塔。最近 \\(n+m\\) 步保持满分辨率，更早的历史按 \\(c\\) 折损分辨率。注意力仍然是 softmax，查询来自当前 token，键来自三层时间尺度。与固定滑窗相比，远距键还在，只是每个键代表 \\(c\\) 步的某种平均或选择。与后来的线性记忆（Infini-Attention）相比，压缩槽仍是显式的、有限个向量，不是一个 \\(d\\times d\\) 的关联矩阵；解读和调试可以看某一个压缩槽的注意力质量。</p><p>相对位置必须告诉模型「这是压缩槽还是近记忆」。若共用同一套距离，网络无法学会对 \\(C\\) 使用不同的读取策略。XL 式相对偏置按记忆类型加不同的可学习向量，是这一区分的实现。梯度方面，压缩函数若对很老的段反传，训练会慢且不稳，通常只反传到最近一次压缩，更老的 \\(C\\) 当作常数状态——于是压缩记忆是有限视野的有损 FIFO，不是真正的无限可微记忆。<span class="marginnote">PG-19 一类以书为单位的基准，对「主题在数十页前出现」敏感，正好打在无损 \\(M\\) 已经覆盖不住、压缩 \\(C\\) 还能留一点痕迹的尺度。短句语言建模上看不出 \\(C\\) 的价值，消融会被平均 PPL 淹没。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Compressive Transformer 的年代没有 7B 指令模型，也没有 FlashAttention。直接把 \\(f\\) 接到今天的 Llama 上，要重做稳定性、与 RoPE 的距离定义、以及 KV 缓存里 \\(C\\) 如何在 decode 时更新。它不能零样本接到已有检查点——压缩器与记忆注意力是训练出来的模块。这与 StreamingLLM、Self-Extend 的训练免费路线相反。</p><p>压缩是有损的：一次压缩再压缩（若实现多层金字塔）会迅速丢失可检索的精确事实。NIAH 式「逐字找回一句随机针」不是它的设计目标；它更擅长主题、风格、长期统计。若产品要的是针，应叠加检索或更高分辨率的记忆，而不是把 \\(c\\) 加大冒充 400k 窗口。</p><p>计算上，注意力可见集是 \\(n+m+m_c\\)，仍比全历史小，但比纯滑窗大。\\(m_c\\) 不是免费的：每个查询都要与压缩槽做点积。把 \\(m_c\\) 开到与 \\(n\\) 同阶，二次项又回来了。合理的配置是 \\(m_c\\) 远小于 \\(n\\)，当作一条细的长程通道。</p><p><span class="marginnote">不要把「压缩记忆」四个字等同于 KV 量化。量化降低的是每个槽的比特，槽数不变、时间对齐不变；Rae 的压缩降低的是槽数，时间对齐变粗。两者可以叠，但故障模式不同：量化伤的是数值，压缩伤的是时间分辨率。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Compressive Transformer 在 XL 无损记忆之外增加压缩记忆，淘汰的激活经 \\(f\\) 留下而不是删除。</li><li>压缩率 \\(c\\) 用时间分辨率换覆盖距离；卷积、池化或注意力池化都可作为 \\(f\\)。</li><li>辅助重构防止压缩槽塌成无信息均值。</li><li>需要训练，不能当已有 LLM 的推理补丁；视野仍受截断 BPTT 限制。</li><li>擅长长程主题式依赖，不保证逐字针检索。</li><li>显式槽位的金字塔与后来的矩阵式无限记忆是不同实现。</li><li>出处：Rae 等，<em>Compressive Transformers for Long-Range Sequence Modelling</em>，2020；架构上衔接 Dai 等 Transformer-XL（2019）。</li></ul>',10))])}const B=t(d,[["render",f]]);export{C as __pageData,B as default};
